#!/usr/bin/env bash
# Downloads the WasteWise frontend sources of a pinned commit (generated by scripts/make_vercel_deploy.py).
set -euo pipefail
SHA="${1:-4381c9ae8f2644812ffb83e5e9d09f25d9781883}"  # regenerate with scripts/make_vercel_deploy.py web --sha <commit>
curl -fsSL --retry 3 "https://codeload.github.com/Madhurchaudhary/Wastewise/tar.gz/$SHA" \
  | tar -xz --strip-components=2 "Wastewise-$SHA/frontend"
echo "WasteWise frontend sources: commit $SHA"
